import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.BIas3y6W.js";const p=JSON.parse('{"title":"Week 12 Lab — Pull requests and agent code","description":"","frontmatter":{"source":"weeks/12-pull-requests/lab.md"},"headers":[],"relativePath":"weeks/12-pull-requests/lab.md","filePath":"weeks/12-pull-requests/lab.md"}'),i={name:"weeks/12-pull-requests/lab.md"};function r(n,e,h,d,l,c){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="week-12-lab--pull-requests-and-agent-code" tabindex="-1">Week 12 Lab — Pull requests and agent code <a class="header-anchor" href="#week-12-lab--pull-requests-and-agent-code" aria-label="Permalink to &quot;Week 12 Lab — Pull requests and agent code&quot;">​</a></h1><blockquote><p>Two studios. In <strong>Studio A</strong> you add one test by hand to your week 11 feature, then merge it into <code>main</code> through your first pull request. In <strong>Studio B</strong> you hunt a bug planted in agent-written code with the AI off, and start a second feature at the feature clinic.</p></blockquote><p><strong>AI-use key:</strong> 🟢 AI on: use AI, following the <a href="./../../resources/safe-loop.html">Safe Loop</a> · 🟡 AI limited: only in the way the step says · 🔴 AI off: close AI chat and <a href="./../../setup/codespaces.html#turn-copilot-off-for-ai-off-activities">turn off completions</a>.</p><p><strong>This week&#39;s rules for agents:</strong> approvals stay on (never autopilot or skip-permissions modes); commit before and after every agent task; read every command before you allow it; the agent never gets your keys. Stuck at any point? See <a href="#troubleshooting">Troubleshooting</a> at the bottom of this page.</p><h2 id="studio-a--your-first-pull-request-75-min" tabindex="-1">Studio A — Your first pull request (75 min) <a class="header-anchor" href="#studio-a--your-first-pull-request-75-min" aria-label="Permalink to &quot;Studio A — Your first pull request (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Block</th><th>Core or If time</th></tr></thead><tbody><tr><td>0:00–0:05</td><td>Recap: last week&#39;s most-missed exit-ticket question</td><td>—</td></tr><tr><td>0:05–0:20</td><td>Concept talk (<a href="https://boyu-zhang-uoi.github.io/building-apps-with-ai/slides/week-12.html" target="_blank" rel="noreferrer">slides</a>)</td><td>—</td></tr><tr><td>0:20–0:30</td><td>Live demo: a pull request from branch to merge</td><td>—</td></tr><tr><td>0:30–1:10</td><td><a href="#part-a1--branches-and-pull-requests-40-min">Part A1 — Branches and pull requests</a> (40 min)</td><td>Core</td></tr><tr><td>—</td><td><a href="#part-a2--start-the-goldfish-test-10-min">Part A2 — Start the Goldfish test</a> (10 min)</td><td>If time</td></tr><tr><td>1:10–1:15</td><td>Checkpoint share: what did the pull request show you that the editor didn&#39;t?</td><td>—</td></tr></tbody></table><h3 id="the-live-demo-a-pull-request-from-branch-to-merge" tabindex="-1">The live demo: a pull request from branch to merge <a class="header-anchor" href="#the-live-demo-a-pull-request-from-branch-to-merge" aria-label="Permalink to &quot;The live demo: a pull request from branch to merge&quot;">​</a></h3><p>Your instructor takes the branch from last week&#39;s demo all the way to <code>main</code>, while you watch for five things: the <strong>description</strong> says what, why and how it was tested; the <strong>checks</strong> run the tests on GitHub; <strong>Files changed</strong> shows the whole diff, read line by line; a <strong>comment</strong> goes on one line; and after the merge, <code>git pull</code> brings <code>main</code> up to date in the Codespace. You&#39;ll do exactly this in Part A1.</p><h3 id="part-a1--branches-and-pull-requests-40-min" tabindex="-1">Part A1 — Branches and pull requests (40 min) <a class="header-anchor" href="#part-a1--branches-and-pull-requests-40-min" aria-label="Permalink to &quot;Part A1 — Branches and pull requests (40 min)&quot;">​</a></h3><p><strong>Core · 🔴 AI off for the test you write in step 2; otherwise no AI needed</strong></p><p><strong>Why:</strong> <code>main</code> is the version that&#39;s deployed, so it should always work. A <strong><a href="./../../resources/glossary.html#pull-request">pull request</a></strong> (PR) proposes merging a branch into <code>main</code> and shows the whole change as one diff, with the automated tests run on it, before it joins. From now on every capstone feature joins <code>main</code> through a pull request; in week 14 a classmate reviews one of yours.</p><ol><li><p><strong>Where you are (2 min).</strong> In your capstone Codespace:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span></span></code></pre></div><p>It lists your branches; <code>*</code> marks the one you&#39;re on. You should be on <code>feature/ac1</code>. If not: <code>git switch feature/ac1</code>. (In a new Codespace, the branch may not be listed yet; <code>git switch feature/ac1</code> still finds it on GitHub.)</p></li><li><p><strong>Add one test by hand (15 min).</strong> Writing a criterion and its test without AI is one of the <a href="./../../resources/without-ai-skills.html#3-write-an-acceptance-criterion-and-a-test-for-it">six skills you must show without AI</a>. Think of one more edge case for AC1 (a name with spaces around it, the same name in different capitals, a name just over a length limit). Add it to <code>SPEC.md</code> as a new criterion, with the next free number, in WHEN … THE APP SHALL … form. Then type a test for it <strong>by hand</strong> in your test file, copying the shape of the tests already there, and run <code>npm test</code>.</p><ul><li>If it <strong>fails</strong>, fix the code by hand until it passes.</li><li>If it <strong>passes</strong> straight away, say why (the code already handles it), and prove the test can fail: change its expected value for a moment, see it fail, change it back.</li></ul><p>Commit (no <code>Assisted-by:</code> line: you wrote it) and sync: <code>git commit -am &quot;Add test for names in different capitals&quot;</code>, then <strong>Sync Changes</strong>.</p></li><li><p><strong>Open the pull request (6 min).</strong> On github.com, open your repository. A banner says your branch had recent pushes: click <strong>Compare &amp; pull request</strong>. (No banner? <strong>Pull requests</strong> → <strong>New pull request</strong>, base <code>main</code>, compare <code>feature/ac1</code>.) Give it a title that says what it does, and a short description:</p><div class="language-markdown vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">markdown</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**What:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Reject empty and duplicate habit names (AC1, AC7).</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**Why:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> SPEC.md AC1; duplicates made the streak count wrong.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**How I tested it:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> npm test (tests 14, pass 14); tried empty, duplicate and different-capitals names in the browser.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-light-font-weight:bold;--shiki-dark:#E1E4E8;--shiki-dark-font-weight:bold;">**AI use:**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> GitHub Copilot agent mode for the AC1 test and code; AC7&#39;s test by hand. Teach-back in PROMPTS.md.</span></span></code></pre></div><p>Click <strong>Create pull request</strong>.</p></li><li><p><strong>Checks (3 min).</strong> Your test workflow runs on the pull request. Wait for the green check. A red ✗? Click <strong>Details</strong> and read which test failed. If your capstone is on Vercel, a comment or check from Vercel links to a <strong><a href="./../../resources/glossary.html#preview-deployment">preview deployment</a></strong> of this branch: open it and try the feature before you merge.</p></li><li><p><strong>Review your own pull request (8 min).</strong> Click <strong>Files changed</strong> and read it as a reviewer would:</p><ul><li>☐ Only the files I meant to change. No <code>.env</code>, no stray files.</li><li>☐ Every line is one I can explain.</li><li>☐ No secrets, no leftover <code>console.log</code> lines or commented-out code.</li><li>☐ The tests in <code>tests/</code> changed only where I added one.</li><li>☐ The description matches what the diff actually does.</li></ul><p>Leave at least one comment on a line (hover over the line → <strong>+</strong>), for example why a check is written the way it is. That&#39;s ordinary code review: keep comments about the code.</p></li><li><p><strong>Merge (3 min).</strong> Click <strong>Merge pull request</strong> → <strong>Confirm merge</strong> → <strong>Delete branch</strong>.</p></li><li><p><strong>Update your Codespace (3 min).</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --oneline</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -5</span></span></code></pre></div><p>The log now shows your commits on <code>main</code>. If your capstone is on Vercel, the merge also redeployed it: open your production URL and try the feature live.</p></li></ol><p><strong>Pairs:</strong> your partner reviews instead (<strong>Files changed</strong> → <strong>Review changes</strong> → <strong>Approve</strong>), then you merge. <strong>Working alone?</strong> Self-review is exactly right; in week 14 a classmate or your instructor reviews a later pull request.</p><p>✅ <strong>Checkpoint:</strong> your first pull request is merged, the branch is deleted, and <code>git log</code> on <code>main</code> shows the feature. More detail: <a href="./../../resources/git-cheatsheet.html#branches-and-pull-requests">branches and pull requests in the Git Cheat Sheet</a>.</p><h3 id="part-a2--start-the-goldfish-test-10-min" tabindex="-1">Part A2 — Start the Goldfish test (10 min) <a class="header-anchor" href="#part-a2--start-the-goldfish-test-10-min" aria-label="Permalink to &quot;Part A2 — Start the Goldfish test (10 min)&quot;">​</a></h3><p><strong>If time · 🟡 AI limited</strong></p><p>Start <a href="./homework.html#1-the-goldfish-test-about-45-min">homework task 1</a>: paste only your <code>SPEC.md</code> into a fresh chat and log what it says it would build. The revision can wait for homework.</p><h3 id="wrap-up-studio-a" tabindex="-1">Wrap up Studio A <a class="header-anchor" href="#wrap-up-studio-a" aria-label="Permalink to &quot;Wrap up Studio A&quot;">​</a></h3><ul><li>☐ First pull request merged; <code>main</code> up to date in your Codespace.</li><li>☐ A hand-written test for a new edge case, in <code>SPEC.md</code> and in <code>tests/</code>.</li><li>☐ Codespace stopped.</li></ul><h2 id="studio-b--agent-code-under-the-microscope-75-min" tabindex="-1">Studio B — Agent code under the microscope (75 min) <a class="header-anchor" href="#studio-b--agent-code-under-the-microscope-75-min" aria-label="Permalink to &quot;Studio B — Agent code under the microscope (75 min)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Time</th><th>Block</th><th>Core or If time</th></tr></thead><tbody><tr><td>0:00–0:05</td><td>Show and tell: two students show their merged pull request&#39;s <strong>Files changed</strong> and read their teach-back. Is it accurate?</td><td>—</td></tr><tr><td>0:05–0:30</td><td><a href="#part-b1--find-the-bug-planted-in-agent-written-code-25-min">Part B1 — Find the bug planted in agent-written code</a> (25 min)</td><td>Core</td></tr><tr><td>0:30–0:55</td><td><a href="#part-b2--feature-clinic-25-min">Part B2 — Feature clinic</a> (25 min)</td><td>Core</td></tr><tr><td>0:55–1:05</td><td><a href="#part-b3--project-time-10-min">Part B3 — Project time</a> (10 min): your clinic feature, with help; explain your first feature to a classmate</td><td>Core; one If time task</td></tr><tr><td>1:05–1:15</td><td>Week 12 exit ticket (🔴 AI off; graded on completion, not correctness)</td><td>—</td></tr></tbody></table><h3 id="part-b1--find-the-bug-planted-in-agent-written-code-25-min" tabindex="-1">Part B1 — Find the bug planted in agent-written code (25 min) <a class="header-anchor" href="#part-b1--find-the-bug-planted-in-agent-written-code-25-min" aria-label="Permalink to &quot;Part B1 — Find the bug planted in agent-written code (25 min)&quot;">​</a></h3><p><strong>Core · 🔴 AI off for the Fixer</strong></p><p><strong>Why:</strong> the agent will write code that is almost right. In one study of 917 students, bugs planted in otherwise-correct AI code led students to fix the code themselves instead of asking the AI again, and those students did better on their next attempt (<a href="https://arxiv.org/pdf/2607.05068" target="_blank" rel="noreferrer">Pădurean et al.</a>). Reading the failure and finding the line is one of the <a href="./../../resources/without-ai-skills.html#1-read-an-error-message-and-find-the-failing-line">six skills you must show without AI</a>.</p><p>Work in pairs at one computer: the <strong>Fixer</strong>&#39;s capstone Codespace, and a <strong>Planter</strong>.</p><ol><li><p><strong>Fixer (2 min).</strong> On <code>main</code>, with <code>git status</code> clean, start a practice branch: <code>git switch -c practice/bug-hunt</code>. Turn the AI off (close Copilot Chat; turn off completions). Turn away from the screen.</p></li><li><p><strong>Planter (3 min).</strong> Open the file in <code>public/lib/</code> that the agent wrote in week 11. Change <strong>one</strong> small thing that a test or the browser would catch: flip <code>&gt;</code> to <code>&gt;=</code>, change a number, remove a <code>!</code> (JavaScript&#39;s <code>not</code>) or a <code>.trim()</code> (JavaScript&#39;s <code>.strip()</code>), or swap two variables. Don&#39;t touch the tests. Save, then commit it so the change doesn&#39;t show as unsaved: <code>git commit -am &quot;Practice&quot;</code>. Say &quot;ready&quot;.</p></li><li><p><strong>Fixer (12 min).</strong> Find it and fix it by hand. No AI, and no <code>git diff</code>, <code>git log -p</code> or <code>git show</code> (they&#39;d show you the answer). Run <code>npm test</code> and read the failure from the top: which test, which file and line, what it expected and what it got. Open the function, reason about it, fix it, and run <code>npm test</code> until it shows <code>fail 0</code>. If <strong>no</strong> test fails, the bug escaped your tests: find it in the browser, and note in <code>TESTS.md</code> the test that would have caught it.</p></li><li><p><strong>Check (3 min).</strong> Now you may look: <code>git diff main</code> shows how your version differs from the original. Nothing, or an equivalent fix you can explain, means you found it.</p></li><li><p><strong>Clean up (2 min).</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restore</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> switch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> branch</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> practice/bug-hunt</span></span></code></pre></div></li><li><p><strong>Talk (3 min).</strong> Which clue found it fastest? Did you want to ask the AI? Swap roles in project time if you both want a turn.</p></li></ol><p><strong>Working alone or online?</strong> Let an AI plant the bug (🟢 AI on for planting only). Paste the function into a chat with: &quot;Change exactly one small thing in this function so it has a subtle bug that a test could catch. Don&#39;t tell me what you changed. Reply only with the full changed function.&quot; Paste the reply over the function on your practice branch, commit it, close the chat, and do step 3 with the AI off.</p><div class="caution custom-block github-alert"><p class="custom-block-title">CAUTION</p><p>Never &quot;fix&quot; a failing test by changing what it expects, unless <code>SPEC.md</code> says the test is wrong. One developer&#39;s &quot;fix it&quot; prompt changed a test&#39;s expected status from 200 to 500 so the test would pass, and the bug stayed (<a href="https://news.ycombinator.com/item?id=48662310" target="_blank" rel="noreferrer">HN discussion</a>).</p></div><p>✅ <strong>Checkpoint:</strong> the Fixer found and fixed the planted bug by hand, or knows which test was missing; the practice branch is deleted.</p><h3 id="part-b2--feature-clinic-25-min" tabindex="-1">Part B2 — Feature clinic (25 min) <a class="header-anchor" href="#part-b2--feature-clinic-25-min" aria-label="Permalink to &quot;Part B2 — Feature clinic (25 min)&quot;">​</a></h3><p><strong>Core · 🟢 AI on: agent mode with approvals on · 🟡 AI limited for the criterion you write · 🔴 AI off for the teach-back</strong></p><p><strong>Why:</strong> two of the four capstone feature types, (c) a data visualization and (d) an external public API, need a pattern you haven&#39;t used yet. The capstone starter includes tested examples of both (<a href="https://github.com/Boyu-Zhang-UOI/vc101-capstone-starter/blob/main/README.md#feature-patterns" target="_blank" rel="noreferrer">feature patterns</a>). Pick the station your pitch needs; the feature you start here is your homework feature.</p><p><strong>Every station uses the same loop</strong> as week 11&#39;s first feature:</p><ol><li>Write the criterion in <code>SPEC.md</code> (🟡 AI limited: you write it).</li><li>Start a branch from an up-to-date <code>main</code>: <code>git switch main</code>, <code>git pull</code>, <code>git switch -c feature/[short-name]</code>.</li><li><strong>Check first:</strong> the test, in its own chat or by hand; see it fail; commit it.</li><li><strong>New chat:</strong> plan first, approve, build; approvals on.</li><li>Green in your own terminal; <code>tests/</code> unchanged; read the diff; try it by hand.</li><li>Teach-back (🔴 AI off), commit with an <code>Assisted-by:</code> line, publish the branch, open a pull request, review it, merge it.</li></ol><p>Today, aim to finish steps 1–3. The rest continues in project time and homework.</p><h4 id="station-c--a-simple-chart" tabindex="-1">Station C — A simple chart <a class="header-anchor" href="#station-c--a-simple-chart" aria-label="Permalink to &quot;Station C — A simple chart&quot;">​</a></h4><p>For capstones that draw a chart from their own data. Read <a href="https://github.com/Boyu-Zhang-UOI/vc101-capstone-starter/blob/main/README.md#a-chart-with-no-libraries" target="_blank" rel="noreferrer">A chart with no libraries</a> in the starter README, then <code>public/lib/chart.js</code> and <code>tests/chart.test.js</code>. The helper draws a bar chart as SVG (a format for drawing shapes in a web page) from rows of <code>{ label, value }</code>, and <code>countBy</code> can count things in your data for you. Most chart bugs are data bugs, so your job is the <strong>data preparation</strong>: the pure function that turns your app&#39;s records into those rows, which is the part you test first.</p><ul><li>Decide what to chart: which numbers, grouped how (per day, per week, per category)? Keep it to one chart.</li><li>Example criterion: &quot;WHEN I have logged sessions on three different days, THE APP SHALL show one bar per day, labeled with the day and its total minutes.&quot;</li><li>The helper adds a text description for screen readers. If the numbers matter, also show them as text (a list or a small table) next to the chart, so anyone who can&#39;t tell the bars apart gets the same information.</li></ul><h4 id="station-d--an-external-api-route" tabindex="-1">Station D — An external API route <a class="header-anchor" href="#station-d--an-external-api-route" aria-label="Permalink to &quot;Station D — An external API route&quot;">​</a></h4><p>For capstones that fetch live data from a public service. Read <a href="https://github.com/Boyu-Zhang-UOI/vc101-capstone-starter/blob/main/README.md#data-from-a-public-api" target="_blank" rel="noreferrer">Data from a public API</a> in the starter README, then <code>api/weather.js</code>, <code>lib/weather.js</code> and <code>tests/weather.test.js</code>. It&#39;s the external-API pattern from week 10, with tests that replace <code>fetch</code> with a fake (a <a href="./../../resources/glossary.html#mock">mock</a>), so they run offline. To use a different API, the README says to copy <code>lib/weather.js</code> and change the address and the step that simplifies the reply.</p><ul><li>Pick your API. Read its terms: whether it needs a key, how many requests it allows, and whether you must credit it. (If it needs a key, the key goes in environment variables, and the feature counts as type (a) instead.)</li><li>Write the check-first tests with a fake <code>fetch</code>: a good answer, a service error or timeout, and bad input.</li><li>Example criterion: &quot;WHEN the weather service doesn&#39;t answer within 10 seconds, THE APP SHALL show &#39;Weather is unavailable right now&#39;, and the rest of the page SHALL keep working.&quot;</li></ul><h4 id="neither-station-fits" tabindex="-1">Neither station fits? <a class="header-anchor" href="#neither-station-fits" aria-label="Permalink to &quot;Neither station fits?&quot;">​</a></h4><p>If your capstone uses (a) an AI feature or (b) a database: for (a), adapt <code>api/ask.js</code> the way you did with your week 9 micro-app, and test the validation of any new input first. For (b), week 13 Studio A connects Supabase safely; today, build and test the pure logic for your data (for example, checking a new entry) in <code>public/lib/</code>. Either way, use the same loop.</p><p>✅ <strong>Checkpoint:</strong> your criterion is in <code>SPEC.md</code>, you&#39;re on a feature branch, and your check-first test fails for the right reason.</p><h3 id="part-b3--project-time-10-min" tabindex="-1">Part B3 — Project time (10 min) <a class="header-anchor" href="#part-b3--project-time-10-min" aria-label="Permalink to &quot;Part B3 — Project time (10 min)&quot;">​</a></h3><p><strong>Core · AI use as each task says</strong></p><p>Use this time for whatever moves you forward most, with help from your instructor:</p><ul><li><strong>Keep going</strong> on your clinic feature, through the same loop, toward a reviewed and merged pull request.</li><li><strong>Deploy</strong>, if your capstone isn&#39;t on Vercel yet: <a href="./../11-agents/homework.html#4-deploy-on-day-one-about-30-min">week 11 homework task 4</a>.</li><li><strong>If time: explain it to a classmate</strong> (🔴 AI off). Open the <strong>Files changed</strong> tab of the pull request you merged in Studio A and walk a neighbor through what the agent changed and why it works. They ask you about one line. A line you couldn&#39;t explain is the one to read again tonight (<a href="./../../resources/without-ai-skills.html#2-explain-any-function-you-committed">Explain any function you committed</a>).</li></ul><p>✅ <strong>Checkpoint:</strong> your clinic feature has a failing check-first test on its branch.</p><h3 id="wrap-up-studio-b" tabindex="-1">Wrap up Studio B <a class="header-anchor" href="#wrap-up-studio-b" aria-label="Permalink to &quot;Wrap up Studio B&quot;">​</a></h3><ul><li>☐ Planted-bug hunt done; practice branch deleted.</li><li>☐ Clinic feature on its own branch, with a check-first test.</li><li>☐ Everything committed and synced; Codespaces stopped.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Problem</th><th>What to do</th></tr></thead><tbody><tr><td><code>git switch feature/ac1</code> says the branch doesn&#39;t exist</td><td>It wasn&#39;t published last week. If you&#39;re in the same Codespace, it&#39;s still there locally: check <code>git branch</code>. Otherwise run <code>git fetch</code>, then try again; if it&#39;s still missing, ask for help before you redo anything</td></tr><tr><td><code>git switch</code> says you have uncommitted changes</td><td>Commit (or discard) them first, so every branch starts from a clean save point</td></tr><tr><td>No <strong>Compare &amp; pull request</strong> banner</td><td>Use <strong>Pull requests</strong> → <strong>New pull request</strong>, base <code>main</code>, compare your branch. Check the branch was published (<code>git push -u origin [branch]</code>)</td></tr><tr><td>The pull request&#39;s check is red</td><td>Click <strong>Details</strong> to see which test failed, fix it on the same branch, commit and push: the pull request updates itself</td></tr><tr><td>No preview link on the pull request</td><td>Your capstone isn&#39;t connected to Vercel yet. Do <a href="./../11-agents/homework.html#4-deploy-on-day-one-about-30-min">week 11&#39;s deploy task</a>; the next push to the branch gets a preview</td></tr><tr><td>The pull request says &quot;This branch has conflicts&quot;</td><td>Stop and ask for help; don&#39;t let the agent &quot;resolve&quot; it blindly. See <a href="./../../resources/troubleshooting.html#i-have-a-merge-conflict">I have a merge conflict</a></td></tr><tr><td><code>git pull</code> on <code>main</code> says &quot;diverged&quot;</td><td>You committed on <code>main</code> in the Codespace while the pull request merged on GitHub. Ask for help before you force anything</td></tr><tr><td>You committed on <code>main</code> instead of a branch</td><td>Don&#39;t let the agent fix it. <code>git switch -c feature/[short-name]</code> keeps the commits on a new branch; ask your instructor before you change <code>main</code></td></tr><tr><td>Planted-bug hunt: no test fails</td><td>The bug escaped your tests. Find it in the browser, then add the missing test to <code>TESTS.md</code> (and, later, to <code>tests/</code>)</td></tr><tr><td>Planted-bug hunt: <code>git branch -D</code> says you&#39;re on that branch</td><td>Run <code>git switch main</code> first</td></tr><tr><td>Station D: a test reaches the real service, or fails offline</td><td>The test must replace <code>fetch</code> with a fake before calling your function. Copy the setup from <code>tests/weather.test.js</code></td></tr><tr><td>Station C: the chart doesn&#39;t appear</td><td>Check that the element in <code>index.html</code> has the id you pass to <code>renderBarChart</code>, and that every value is a number of 0 or more. Open DevTools&#39; Console for errors</td></tr><tr><td>The agent wants to install a chart or HTTP library</td><td>Stop. The starter&#39;s patterns need none. If you really need one, check it on npmjs.com first (<a href="./../../setup/safety-contract.html#6-i-check-packages-before-i-install-them">Safety Contract, rule 6</a>)</td></tr></tbody></table>`,53)])])}const g=t(i,[["render",r]]);export{p as __pageData,g as default};
